#if canImport(UIKit)
import UIKit

/// ProcrastiMate's app icon without its tile, 22 points at 3×. Rendered by `scripts/procrastimate-icon.ts` from ProcrastiMate's `app-icon.svg`.
enum ProcrastimateIcon {
    static let image = UIImage(data: Data(base64Encoded: base64)!, scale: 3)!.withRenderingMode(.alwaysOriginal)

    private static let base64 = ""
}
#endif
